at survives folds; `list` shows them. 'file' takes path+why instead of text; 'steering' belongs to an anchor (scopeAnchor, default newest). Refused when the user disabled the continuity ledger (continuity.capture=false).\n\n`name` (anchor) and `newLabel` (rewind) write into one shared anchor namespace: labels are unique on the active branch — both actions refuse a name that already exists — and everything written there is addressable as a future `rewindTo`. Avoid the reserved `anchor:` prefix.","name":"navigate_tree","output_schema":null,"parameters":{"type":"object","required":["action"],"properties":{"action":{"anyOf":[{"type":"string","const":"anchor"},{"type":"string","const":"rewind"},{"type":"string","const":"list"},{"type":"string","const":"pin"}],"description":"Which operation to perform."},"name":{"type":"string","description":"Required when action='anchor'. Kebab-case milestone label, max 40 chars."},"rewindTo":{"type":"string","description":"Required when action='rewind'. Kebab-case name of an existing anchor on the active branch to rewind to."},"newLabel":{"type":"string","description":"Required when action='rewind'. Kebab-case label for the resulting branch_summary entry; reusable as a future rewindTo."},"summaryFocus":{"type":"string","description":"Required when action='rewind'; ≥20 chars after trim. Encode: (1) the user's most recent instruction verbatim, (2) what's done in the collapsed segment, (3) what's left to do as a next action; if the user authorized continuing, name the next work item, not a report or wrap-up."},"kind":{"anyOf":[{"type":"string","const":"sub-goal"},{"type":"string","const":"decision"},{"type":"string","const":"fact"},{"type":"string","const":"file"},{"type":"string","const":"steering"}],"description":"Required when action='pin'. Your sub-goal, a decision you made, a key fact, a file pointer, or steering that lapses when its anchor is folded."},"text":{"type":"string","description":"Required when action='pin' unless kind='file'. What to remember, max 500 chars."},"path":{"type":"string","description":"Required when action='pin' and kind='file'. File path."},"lines":{"type":"string","description":"Optional with kind='file': N or N-M."},"why":{"type":"string","description":"Required when action='pin' and kind='file'. Why the file matters."},"scopeAnchor":{"type":"string","description":"Anchor name for kind='steering' (default: newest anchor); optional for 'sub-goal'."}}},"strict":false}],"top_logprobs":0,"top_p":0.98,"truncation":"disabled","usage":{"attribution":{"items":{"msg_01cc62bba9f1a192016adf8b1ea8d887d2a2c37aab05e1ef3c":{"cache_write_tokens":0,"cached_tokens":101,"content":[{"cache_write_tokens":0,"cached_tokens":101,"input_tokens":101,"output_tokens":0}],"input_tokens":101,"output_tokens":0},"msg_01cc62bba9f1a192016adf8b1eaad887d2a586f698c6b1b83a":{"cache_write_tokens":0,"cached_tokens":485,"content":[{"cache_write_tokens":0,"cached_tokens":485,"input_tokens":485,"output_tokens":0}],"input_tokens":485,"output_tokens":0},"msg_01cc62bba9f1a192016adf8b1eaaf087d299fdad0bda0cf257":{"cache_write_tokens":0,"cached_tokens":4793,"content":[{"cache_write_tokens":0,"cached_tokens":4793,"input_tokens":4793,"output_tokens":0}],"input_tokens":4793,"output_tokens":0},"msg_pi_2":{"cache_write_tokens":0,"cached_tokens":25,"content":[{"cache_write_tokens":0,"cached_tokens":25,"input_tokens":25,"output_tokens":0}],"input_tokens":25,"output_tokens":0},"msg_01cc62bba9f1a192016adf8b1eab0887d2a0e880ad0b067cbc":{"cache_write_tokens":0,"cached_tokens":4793,"content":[{"cache_write_tokens":0,"cached_tokens":4793,"input_tokens":4793,"output_tokens":0}],"input_tokens":4793,"output_tokens":0},"msg_pi_4":{"cache_write_tokens":0,"cached_tokens":25,"content":[{"cache_write_tokens":0,"cached_tokens":25,"input_tokens":25,"output_tokens":0}],"input_tokens":25,"output_tokens":0},"msg_01cc62bba9f1a192016adf8b1eab2087d2bb93083d38842874":{"cache_write_tokens":0,"cached_tokens":40,"content":[{"cache_write_tokens":0,"c